import json, re

def validate_order(status, body_text):
    errors = []
    if status != 201:
        errors.append('status')
    try:
        body = json.loads(body_text)
    except ValueError:
        return errors + ['json']
    if not isinstance(body.get('id'), str) or not re.fullmatch(r'ORD-\d+', body['id']):
        errors.append('id')
    items = body.get('items')
    if not isinstance(items, list) or not items:
        errors.append('items')
    else:
        expected = sum(i['price'] * i['qty'] for i in items)
        if abs(body.get('total', -1) - expected) > 0.001:
            errors.append('total')
    return errors

