import re

def run_chain(steps, responses):
    variables, sent = {}, []
    for step in steps:
        path = re.sub(r'\$\{(\w+)\}', lambda m: variables.get(m.group(1), m.group(0)), step['path'])
        sent.append(path)
        resp = responses.get(path, {})
        for var, key in step.get('extract', {}).items():
            variables[var] = str(resp[key]) if key in resp else 'NOT_FOUND'
    return sent
